'use client';

import { useEffect, useRef, useState, type ReactNode } from 'react';
import { usePointerDrag } from './use-pointer-drag';
import './swipe-action-row.css';

export interface SwipeAction {
  id: string;
  label: string;
  tone?: 'neutral' | 'danger';
}

export interface SwipeActionRowProps {
  children: ReactNode;
  /** Short name of the row, used in the "Show actions" button label. */
  name: string;
  actions: SwipeAction[];
  onAction: (id: string) => void;
  className?: string;
}

const ACTION_WIDTH = 84;

/**
 * Swipe the row left to uncover its actions; it snaps open or closed. Up and
 * down still scroll on touch. The "⋯" button does the same without a
 * gesture, and hidden actions stay out of the tab order.
 */
export function SwipeActionRow({
  children,
  name,
  actions,
  onAction,
  className = '',
}: SwipeActionRowProps) {
  const width = actions.length * ACTION_WIDTH;
  const [open, setOpen] = useState(false);
  const [offset, setOffset] = useState<number | null>(null);
  const first = useRef<HTMLButtonElement>(null);
  const toggle = useRef<HTMLButtonElement>(null);
  const viaButton = useRef(false);

  useEffect(() => {
    if (open && viaButton.current) first.current?.focus();
    viaButton.current = false;
  }, [open]);

  const drag = usePointerDrag({
    onStart: (event) => {
      if ((event.target as HTMLElement).closest('button')) return false;
    },
    onMove: ({ dx }) => {
      const base = open ? -width : 0;
      setOffset(Math.max(-width - 24, Math.min(0, base + dx)));
    },
    onEnd: ({ dx, vx }, cancelled) => {
      const base = open ? -width : 0;
      const end = base + dx;
      setOffset(null);
      if (cancelled) return;
      setOpen(vx < -0.4 || (vx <= 0.4 && end < -width / 2));
    },
  });

  const x = offset ?? (open ? -width : 0);
  return (
    <div
      className={`mg-swipe ${className}`}
      data-dragging={offset !== null}
      onKeyDown={(event) => {
        if (event.key === 'Escape' && open) {
          setOpen(false);
          toggle.current?.focus();
        }
      }}
    >
      <div className='mg-swipe__actions' style={{ width }}>
        {actions.map((action, index) => (
          <button
            key={action.id}
            ref={index === 0 ? first : undefined}
            type='button'
            tabIndex={open ? 0 : -1}
            aria-hidden={!open}
            data-tone={action.tone ?? 'neutral'}
            onClick={() => {
              setOpen(false);
              onAction(action.id);
            }}
          >
            {action.label}
          </button>
        ))}
      </div>
      <div
        className='mg-swipe__front'
        style={{ transform: `translateX(${x}px)` }}
        {...drag}
      >
        <div className='mg-swipe__content'>{children}</div>
        <button
          ref={toggle}
          type='button'
          className='mg-swipe__more'
          aria-expanded={open}
          aria-label={`${open ? 'Hide' : 'Show'} actions for ${name}`}
          onClick={() => {
            viaButton.current = true;
            setOpen((value) => !value);
          }}
        >
          ⋯
        </button>
      </div>
    </div>
  );
}

.mg-swipe {
  position: relative;
  overflow: hidden;
  border-radius: 10px;
  background: var(--mg-ink, #0c1738);
}

.mg-swipe__actions {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  display: flex;
}

.mg-swipe__actions button {
  flex: 1;
  border: 0;
  background: #25345f;
  color: #fff;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.mg-swipe__actions button[data-tone='danger'] {
  background: #b3122c;
}

.mg-swipe__actions button:focus-visible {
  outline: 3px solid var(--mg-green, #b6ff3b);
  outline-offset: -3px;
}

.mg-swipe__front {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 56px;
  padding-left: 14px;
  background: #fff;
  color: var(--mg-ink, #0c1738);
  /* Horizontal drags are ours; vertical swipes still scroll the page. */
  touch-action: pan-y;
  transition: transform 300ms cubic-bezier(0.2, 0.9, 0.3, 1.1);
  user-select: none;
  -webkit-user-select: none;
  cursor: grab;
}

.mg-swipe[data-dragging='true'] .mg-swipe__front {
  transition: none;
  cursor: grabbing;
}

.mg-swipe__content {
  flex: 1;
  min-width: 0;
}

.mg-swipe__more {
  flex: none;
  width: 48px;
  height: 48px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: #46527a;
  font-size: 22px;
  cursor: pointer;
}

.mg-swipe__more:focus-visible {
  outline: 2px solid var(--mg-accent, #164cff);
  outline-offset: -2px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-swipe__front {
    transition: none;
  }
}

'use client';

import { useRef, type PointerEvent as ReactPointerEvent } from 'react';

export interface DragState {
  /** Distance from where the drag started, in pixels. */
  dx: number;
  dy: number;
  /** Pointer position in viewport coordinates. */
  clientX: number;
  clientY: number;
  /** Smoothed velocity in pixels per millisecond. */
  vx: number;
  vy: number;
}

export interface PointerDragOptions {
  /** Return false to ignore this press. */
  onStart?: (event: ReactPointerEvent<HTMLElement>) => boolean | void;
  onMove?: (drag: DragState) => void;
  /**
   * `cancelled` is true when the browser took the gesture over, for example
   * to scroll the page on touch.
   */
  onEnd?: (drag: DragState, cancelled: boolean) => void;
}

interface Active {
  id: number;
  startX: number;
  startY: number;
  lastX: number;
  lastY: number;
  lastTime: number;
  vx: number;
  vy: number;
}

/**
 * Pointer-capture dragging for mouse, pen and touch. Spread the returned
 * handlers on the element that starts the drag. Pair it with a CSS
 * `touch-action` that leaves the scroll axis you still want to the browser.
 */
export function usePointerDrag(options: PointerDragOptions) {
  const latest = useRef(options);
  latest.current = options;
  const active = useRef<Active | null>(null);

  const snapshot = (a: Active, x: number, y: number): DragState => ({
    dx: x - a.startX,
    dy: y - a.startY,
    clientX: x,
    clientY: y,
    vx: a.vx,
    vy: a.vy,
  });

  const finish = (
    event: ReactPointerEvent<HTMLElement>,
    cancelled: boolean
  ) => {
    const a = active.current;
    if (!a || a.id !== event.pointerId) return;
    active.current = null;
    if (event.currentTarget.hasPointerCapture?.(event.pointerId))
      event.currentTarget.releasePointerCapture(event.pointerId);
    // A pause before release means the pointer was not really flung.
    if (event.timeStamp - a.lastTime > 150) {
      a.vx = 0;
      a.vy = 0;
    }
    latest.current.onEnd?.(
      snapshot(a, event.clientX, event.clientY),
      cancelled
    );
  };

  return {
    onPointerDown(event: ReactPointerEvent<HTMLElement>) {
      if (event.button !== 0 || active.current) return;
      if (latest.current.onStart?.(event) === false) return;
      event.currentTarget.setPointerCapture?.(event.pointerId);
      active.current = {
        id: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        lastX: event.clientX,
        lastY: event.clientY,
        lastTime: event.timeStamp,
        vx: 0,
        vy: 0,
      };
    },
    onPointerMove(event: ReactPointerEvent<HTMLElement>) {
      const a = active.current;
      if (!a || a.id !== event.pointerId) return;
      const dt = Math.max(1, event.timeStamp - a.lastTime);
      a.vx = a.vx * 0.6 + ((event.clientX - a.lastX) / dt) * 0.4;
      a.vy = a.vy * 0.6 + ((event.clientY - a.lastY) / dt) * 0.4;
      a.lastX = event.clientX;
      a.lastY = event.clientY;
      a.lastTime = event.timeStamp;
      latest.current.onMove?.(snapshot(a, event.clientX, event.clientY));
    },
    onPointerUp(event: ReactPointerEvent<HTMLElement>) {
      finish(event, false);
    },
    onPointerCancel(event: ReactPointerEvent<HTMLElement>) {
      finish(event, true);
    },
  };
}
